 sum_rows:=0;
 FOR piece IN SELECT value FROM jsonb_array_elements(rows) LOOP
  IF piece->>'table_complete'<>'true' OR piece->>'table_row_count'<>'1' OR piece->>'manifest'<>'customer_financial_fragments_v1' THEN RAISE EXCEPTION 'financial_table_projection_incomplete';END IF;
  row_text:=piece->>'json_fragment';row_doc:=trim(row_text)::jsonb;sum_rows:=sum_rows+1;
  IF piece->>'table'='sandy_commerce_configuration' AND(row_doc->>'next_invoice_number'<>'9007199254740993' OR jsonb_typeof(row_doc->'next_invoice_number')<>'string') THEN RAISE EXCEPTION 'financial_numbering_precision_lost';END IF;
  IF piece->>'table'='sandy_commerce_entry_lines' AND(row_doc->>'debit_minor'<>'9223372036854775807' OR jsonb_typeof(row_doc->'debit_minor')<>'string') THEN RAISE EXCEPTION 'financial_bigint_precision_lost';END IF;
