  IF piece->>'table'='sandy_commerce_invoices' AND(row_doc->>'total_minor'<>'922337203685477580700000' OR jsonb_typeof(row_doc->'total_minor')<>'string' OR row_doc->'items' IS DISTINCT FROM valid_items) THEN RAISE EXCEPTION 'financial_numeric_or_invoice_item_precision_lost';END IF;
  IF piece->>'table' IN('sandy_commerce_consents','sandy_commerce_entitlements') AND row_doc->>'revoked_at' IS NULL THEN RAISE EXCEPTION 'financial_latest_revocation_omitted';END IF;
  IF piece->>'table_row_chain_sha256' IS DISTINCT FROM encode(extensions.digest(encode(extensions.digest(public.sandy_tenant_financial_manifest_v1()->>'manifest_sha256'||':'||(piece->>'table'),'sha256'),'hex')||E'\n'||row_text,'sha256'),'hex') THEN RAISE EXCEPTION 'financial_row_chain_invalid';END IF;
 END LOOP;
