 refused:=false;BEGIN PERFORM * FROM public.sandy_tenant_fragment_capture_v1(tenant,'unreviewed_manifest');EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'tenant_content_schema_changed' THEN RAISE;END IF;refused:=true;END;
