 refused:=false;BEGIN PERFORM * FROM public.sandy_tenant_financial_capture_v1(tenant);EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'tenant_financial_nonfinite_decimal_refused' THEN RAISE;END IF;refused:=true;END;
 IF NOT refused THEN RAISE EXCEPTION 'financial_nonfinite_numeric_exported';END IF;
