 refused:=false;BEGIN PERFORM * FROM public.sandy_tenant_financial_capture_v1(tenant);EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'tenant_financial_nonfinite_timestamp_refused' THEN RAISE;END IF;refused:=true;END;
 IF NOT refused THEN RAISE EXCEPTION 'financial_infinite_timestamp_exported';END IF;
