 refused:=false;BEGIN PERFORM * FROM public.sandy_tenant_financial_capture_v1(tenant);EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'tenant_financial_parent_ownership_refused' THEN RAISE;END IF;refused:=true;END;
