 SELECT encode(extensions.digest(jsonb_agg(part ORDER BY(part->>'sequence')::integer)::text,'sha256'),'hex') INTO before_sha FROM public.sandy_tenant_financial_capture_v1(tenant)part;
 SELECT encode(extensions.digest(jsonb_agg(part ORDER BY(part->>'sequence')::integer)::text,'sha256'),'hex') INTO after_sha FROM public.sandy_tenant_financial_capture_v1(tenant)part;
